SELECT a.automation_id,t.automation_id AS timing_automation_id,a.kind,a.revision,a.definition_json,a.legacy_timing_json,a.state,a.creator_json,a.slot_session_key,CAST(t.next_due_ms AS TEXT) AS next_due_ms,CAST(t.admitted_through_ms AS TEXT) AS admitted_through_ms,CAST(t.imported_watermark_local_ms AS TEXT) AS imported_watermark_local_ms,t.occupying_firing_id,t.waiting_firing_id,t.occupying_external_run FROM automations a LEFT JOIN automation_timing t USING(automation_id) WHERE a.automation_id=?;
